"""Verus contract export for Rust specs."""

from __future__ import annotations

import os
import shutil
import subprocess
import tempfile
from pathlib import Path
from typing import Any

from .harness import _rust_expr, _scalar_only
from .model import Spec

__all__ = ["export_verus", "check_verus"]


def export_verus(spec: Spec) -> str:
    scalars = _scalar_only(spec)
    lines = [
        "// Generated by VeriSpec. DO NOT EDIT.",
        f"// Spec: {spec.path} (format v{spec.spec_version})",
        "",
        "use vstd::prelude::*;",
        "",
        "pub struct State {",
    ]
    for n in scalars:
        lines.append(f"    pub {n}: i64,")
    # collection vars as comments
    for n, v in spec.vars.items():
        if n in scalars:
            continue
        lines.append(f"    // collection var {n}: not expressible in this skeleton")
    lines.append("}")
    lines.append("")
    # invariants spec fn
    inv_exprs = []
    for inv in spec.invariants:
        inv_exprs.append(f"        {_rust_expr(inv['expr'], spec)}")
    lines.append("pub spec fn inv(s: State) -> bool {")
    if inv_exprs:
        lines.append("    " + " && ".join(e.strip() for e in inv_exprs))
    else:
        lines.append("    true")
    lines.append("}")
    lines.append("")
    # actions
    for action in spec.actions:
        params = ", ".join(f"{p}: i64" for p in action.params.keys())
        lines.append(f"pub fn {action.name}(s: &mut State, {params})")
        req_parts = ["inv(*s)"] + [_rust_expr(r, spec) for r in (action.requires or [])]
        lines.append("    requires")
        lines.append("        " + " && ".join(req_parts) + ",")
        eff_parts = ["inv(*s)"]
        for k, v in (action.effects or {}).items():
            eff_parts.append(f"true /* effect {k} */")
        lines.append("    ensures")
        lines.append("        " + " && ".join(eff_parts) + ",")
        lines.append("{")
        lines.append("    // TODO: implementation")
        lines.append("}")
        lines.append("")
    return "\n".join(lines) + "\n"


def check_verus(spec: Spec, crate: str | None = None, timeout: int = 120) -> dict[str, Any]:
    if shutil.which("verus") is None:
        return {"status": "skipped", "message": "verus not found on PATH", "guarantee": None}
    # write contract
    fd, path = tempfile.mkstemp(suffix=".rs")
    try:
        with os.fdopen(fd, "w") as f:
            f.write(export_verus(spec))
        cmd = ["verus", path]
        if crate:
            cmd = ["verus", "--crate-type", "lib", path]
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        ok = proc.returncode == 0
        return {
            "status": "ok" if ok else "violation",
            "message": (proc.stdout + proc.stderr).strip(),
            "guarantee": "proved" if ok else "violation-found",
            "returncode": proc.returncode,
        }
    except subprocess.TimeoutExpired:
        return {"status": "unknown", "message": "verus timed out", "guarantee": "unknown"}
    finally:
        try:
            os.unlink(path)
        except OSError:
            pass
